// 1. Obtener variables de entorno con valores por defecto seguros
const key = env.get('IOT_DEVICE_INGEST_KEY') || 'local-iot-ingest';
const backendUrl = env.get('BACKEND_INGEST_URL') || 'http://backend:4000/api/iot/ingest';

// 2. Health check por método GET (ej: directo desde navegador o monitoreo)
if (msg.req && msg.req.method === 'GET') {
    msg.statusCode = 200;
    msg.headers = { 'content-type': 'application/json' };
    msg.payload = { status: 'ok', service: 'node-red-telemetry', message: 'Servicio de telemetría ESP32 activo' };
    return [null, msg];
}

// 3. Asegurar que msg.payload sea un objeto (maneja String, Buffer u Objeto)
let body = msg.payload;
if (typeof body === 'string') {
    try {
        body = JSON.parse(body);
    } catch (e) {
        msg.statusCode = 400;
        msg.headers = { 'content-type': 'application/json' };
        msg.payload = { message: 'El cuerpo de la solicitud no es un JSON válido.' };
        return [null, msg];
    }
} else if (Buffer.isBuffer(body)) {
    try {
        body = JSON.parse(body.toString());
    } catch (e) {
        msg.statusCode = 400;
        msg.headers = { 'content-type': 'application/json' };
        msg.payload = { message: 'El cuerpo de la solicitud no es un JSON válido.' };
        return [null, msg];
    }
}

// 4. Comprobación de salud / ping desde el frontend para verificar disponibilidad de Node-RED
if (body && (body.ping === true || body.health === true)) {
    msg.statusCode = 200;
    msg.headers = { 'content-type': 'application/json' };
    msg.payload = { status: 'ok', service: 'node-red-telemetry', message: 'Flujo activo' };
    return [null, msg];
}

// 5. Validación segura de cabecera o parámetro de autenticación
const reqHeaders = msg.req?.headers || {};
const incomingKey = reqHeaders['x-device-key'] || reqHeaders['X-Device-Key'] || body?.deviceKey || msg.req?.query?.deviceKey || msg.req?.query?.key;

if (!key || incomingKey !== key) {
    msg.statusCode = 401;
    msg.headers = { 'content-type': 'application/json' };
    msg.payload = { message: 'Credencial del dispositivo inválida o ausente en el encabezado x-device-key.' };
    return [null, msg];
}

// 6. Extracción y conversión segura a números
const deviceId = typeof body?.deviceId === 'string' ? body.deviceId.trim() : '';
const temp = (body?.temperature !== undefined && body?.temperature !== null && body?.temperature !== '') ? Number(body.temperature) : NaN;
const hum = (body?.humidity !== undefined && body?.humidity !== null && body?.humidity !== '') ? Number(body.humidity) : NaN;
const pres = (body?.pressure !== undefined && body?.pressure !== null && body?.pressure !== '') ? Number(body.pressure) : null;
const rain = (body?.precipitation !== undefined && body?.precipitation !== null && body?.precipitation !== '') ? Number(body.precipitation) : null;

// 7. Validaciones de formato y rangos
const validId = /^[a-zA-Z0-9_-]{2,100}$/.test(deviceId);
const validTemperature = Number.isFinite(temp) && temp >= -80 && temp <= 100;
const validHumidity = Number.isFinite(hum) && hum >= 0 && hum <= 100;
const validPressure = pres === null || (Number.isFinite(pres) && pres >= 300 && pres <= 1200);
const validRain = rain === null || (Number.isFinite(rain) && rain >= 0 && rain <= 10000);

if (!validId || !validTemperature || !validHumidity || !validPressure || !validRain) {
    msg.statusCode = 400;
    msg.headers = { 'content-type': 'application/json' };
    msg.payload = { 
        message: 'La lectura de sensores contiene valores no válidos.',
        details: { validId, validTemperature, validHumidity, validPressure, validRain }
    };
    return [null, msg];
}

// 8. Preparar mensaje para el nodo "Guardar en API y PostgreSQL" (HTTP Request)
msg.url = backendUrl;
msg.method = 'POST';
msg.headers = { 
    'content-type': 'application/json', 
    'x-ingest-key': key 
};
msg.payload = {
    deviceId: deviceId,
    temperature: Number(temp.toFixed(2)),
    humidity: Number(hum.toFixed(2)),
    pressure: pres !== null ? Number(pres.toFixed(2)) : null,
    precipitation: rain !== null ? Number(rain.toFixed(2)) : null
};

// Salida 1: Hacia "Guardar en API y PostgreSQL"
// Salida 2: null (no se activa "Rechazar solicitud")
return [msg, null];
